    { const autoA = R.parisAuto(d.ddn, d.dateDiag); if (d.pathologie !== 'RCH' && !d.paris.A && autoA) d.paris.A = autoA; } /* proposition d'âge au diagnostic mémorisée dans le brouillon */
    const app = w.bilan.filter(b => b.statut !== 'na'), fait = app.filter(b => b.statut.startsWith('fait')).length;
    const idBody = `<div class="form-grid">${field('Nom', 'nom', 'text', { attrs: 'style="text-transform:uppercase"' })}${field('Prénom', 'prenom', 'text')}${field('N° de dossier (IPP)', 'ipp', 'text', { attrs: 'placeholder="laisser vide : numéro automatique"', hint: 'identifiant du patient dans le système de l’hôpital ; sinon numéro généré par Ryze' })}
      ${field('Date de naissance', 'ddn', 'date')}${field('Âge (si date de naissance inconnue)', 'age', 'number', { attrs: 'min="0" max="120" placeholder="ans"', hint: 'une date de naissance approximative est enregistrée (âge estimé)' })}<div class="field"><label>Sexe</label><select data-change="wBindR" data-k="sexe"><option value="F"${d.sexe === 'F' ? ' selected' : ''}>Femme</option><option value="M"${d.sexe === 'M' ? ' selected' : ''}>Homme</option></select></div>${field('Téléphone', 'tel', 'tel')}
      ${field('Poids (kg)', 'poids', 'number', { attrs: 'step="0.1"' })}${field('Taille (cm)', 'taille', 'number')}<div class="field"><label>Médecin référent</label><select data-change="wBind" data-k="medecinId">${opt(medecins(), u => u.id, u => R.userName(u.id), d.medecinId)}</select></div></div><div id="w-doublon">${doublonHTML(w)}</div>`;
    const malBody = `<div class="form-grid"><div class="field"><label>Pathologie</label><select data-change="wBindR" data-k="pathologie">${opt(Object.keys(R.PATHOS), k => k, k => R.PATHOS[k].label, d.pathologie)}</select></div>${field('Date du diagnostic', 'dateDiag', 'date')}<div class="field span3"><label class="check"><input type="checkbox" data-change="wAtcd" data-k="oui"${d.atcdFam && d.atcdFam.oui ? ' checked' : ''}><span><b>Antécédent familial de MICI</b><span>maladie inflammatoire de l’intestin chez un parent proche</span></span></label></div>${d.atcdFam && d.atcdFam.oui ? `<div class="field"><label>Type</label><select data-change="wAtcd" data-k="type"><option value="">— Choisir —</option>${R.ATCD_TYPES.map(t => `<option${d.atcdFam.type === t ? ' selected' : ''}>${t}</option>`).join('')}</select></div><div class="field span2"><label>Chez qui, précisions</label><input type="text" data-input="wAtcd" data-k="qui" value="${esc(d.atcdFam.qui || '')}" placeholder="ex. père (Crohn, diagnostiqué à 25 ans), cousine germaine"></div>` : ''}<div class="field"><label>Consanguinité des parents</label><select data-change="wBind" data-k="consanguinite">${opt(Object.keys(R.CONSANG), k => k, k => R.CONSANG[k], d.consanguinite || '')}</select><span class="hint">à préciser pour les formes à début précoce (MICI monogéniques, immunodéficience)</span></div></div><div class="caps mt16 mb8">Classification de Paris <span class="muted" style="text-transform:none;letter-spacing:0;font-weight:400">— ${esc(R.parisCode(d.paris, d.pathologie) || 'non renseignée')}</span></div>${R.formParis(d.paris, d.pathologie, 'w', R.parisAuto(d.ddn, d.dateDiag))}`;
    const atcdBody = `<div class="form-grid">${field('Traitements associés', 'traitementsAssocies', 'text', { attrs: 'placeholder="ex. azathioprine 150 mg/j, mésalazine 4 g/j"' })}${field('Allergies', 'allergies', 'text', { attrs: 'placeholder="ex. pénicilline (urticaire)"' })}${field('Biothérapies antérieures', 'antecedentsBio', 'text', { attrs: 'placeholder="ex. infliximab 2019–2024, perte de réponse (ADA+)"' })}${field('Comorbidités / facteurs de risque', 'comorbidites', 'text', { span: 3, attrs: 'placeholder="ex. tabagisme actif, antécédent de zona, insuffisance cardiaque"' })}</div>`;
    return section(w, 0, 'Identité', d.nom || d.prenom ? `${(d.nom || '—').toUpperCase()} ${d.prenom || '—'} · ${d.ipp || 'n° automatique'} · ${d.poids || '—'} kg` : 'à compléter', idBody)
      + section(w, 1, 'Maladie', `${R.PATHOS[d.pathologie]?.label}${R.parisCode(d.paris, d.pathologie) ? ' · ' + R.parisCode(d.paris, d.pathologie) : ''}${R.sevTxt(d.paris) ? ' · ' + R.sevTxt(d.paris) : ''}`, malBody)
      + section(w, 2, 'Antécédents et traitements', [d.traitementsAssocies, d.allergies, d.antecedentsBio].filter(Boolean).join(' · ') || 'rien renseigné', atcdBody)
