    const premiereTxt = premiere ? (() => { const d = R.doseProchaine(p, premiere), voie = premiere.voie === 'IV' ? 'perfusion IV' : premiere.voie === 'SC' ? 'injection sous-cutanée à l’hôpital de jour' : premiere.voie || ''; return `<p class="impr-premiere"><b>Première séance${(premiere.cycle || 1) > 1 ? ' de ' + esc(dciI(premiere.protocoleId || p.protocoleId)) : ''} prévue le ${fdI(premiere.datePrevue)}${premiere.heure ? ' à ' + esc(premiere.heure) : ''}</b> — ${esc([premiere.label, (premiere.phase || '').toLowerCase(), voie].filter(Boolean).join(', '))}${d.texte ? ' : ' + esc(d.texte) : ''}</p>`; })() : '';
